'use strict';

// MODULES //

var map = require( '@stdlib/array/base/map' );
var symbol2alias = require( '@stdlib/plot/base/symbol2alias' );


// MAIN //

/**
* Converts an array of symbol aliases and/or shorthands to canonical symbol aliases.
*
* ## Notes
*
* -   If unable to resolve an alias for an element of the input array, the corresponding element in the output array is `null`.
*
* @param {Collection<string>} symbols - symbol aliases and/or shorthands
* @returns {Array} canonical symbol aliases
*
* @example
* var v = symbols2aliases( [ 'o', 's' ] );
* // returns [ 'circle', 'square' ]
*
* v = symbols2aliases( [ 'o', 'beep' ] );
* // returns [ 'circle', null ]
*/
function symbols2aliases( symbols ) {
	return map( symbols, symbol2alias );
}


// EXPORTS //

module.exports = symbols2aliases;
